def refund_order(
    tenant: str,
    request_id: str,
    order_id: str,
    amount_cents: int,
    reason: str,
) -> IdemResult:
    request_hash = _fingerprint((SCOPE_REFUND, order_id, amount_cents, reason))
    conn = connect()
